DROP TABLE IF EXISTS golden.t;
CREATE TABLE golden.t (id INT PRIMARY KEY, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
SELECT GROUP_CONCAT(CONCAT_WS(':', COLUMN_NAME, CASE WHEN CAST(LOWER(CONCAT(EXTRA,' ')) AS BINARY) IN (CAST('' AS BINARY),CAST('default_generated' AS BINARY)) THEN '' WHEN CAST(LOWER(CONCAT(EXTRA,' ')) AS BINARY) IN (CAST('on update current_timestamp' AS BINARY),CAST('on update current_timestamp()' AS BINARY),CAST('on update current_timestamp(0)' AS BINARY),CAST('default_generated on update current_timestamp' AS BINARY),CAST('default_generated on update current_timestamp()' AS BINARY),CAST('default_generated on update current_timestamp(0)' AS BINARY)) THEN 'on update current_timestamp' ELSE '<unrecognized-extra>' END) ORDER BY ORDINAL_POSITION SEPARATOR '|') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='golden' AND TABLE_NAME='t' AND COLUMN_NAME IN ('created_at','updated_at');
SELECT GROUP_CONCAT(CONCAT_WS(':', COLUMN_NAME, COALESCE(HEX(EXTRA),'<null>'), CHARSET(EXTRA), COLLATION(EXTRA), COLLATION(CONCAT(EXTRA,' ')), HEX(CONCAT(EXTRA,' ')), CASE WHEN CAST(LOWER(CONCAT(EXTRA,' ')) AS BINARY) IN (CAST('' AS BINARY),CAST('default_generated' AS BINARY)) THEN '' WHEN CAST(LOWER(CONCAT(EXTRA,' ')) AS BINARY) IN (CAST('on update current_timestamp' AS BINARY),CAST('on update current_timestamp()' AS BINARY),CAST('on update current_timestamp(0)' AS BINARY),CAST('default_generated on update current_timestamp' AS BINARY),CAST('default_generated on update current_timestamp()' AS BINARY),CAST('default_generated on update current_timestamp(0)' AS BINARY)) THEN 'on update current_timestamp' ELSE '<unrecognized-extra>' END) ORDER BY ORDINAL_POSITION SEPARATOR '|') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='golden' AND TABLE_NAME='t' AND COLUMN_NAME IN ('created_at','updated_at');
DROP TABLE golden.t;
SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='golden' AND TABLE_NAME='t';
